fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    val exposureTimeSec = exposureTimeNs.toDouble() / 1_000_000_000.0
    if (exposureTimeSec >= 1.0) {
        return String.format("%.1fs", exposureTimeSec)
    }
    val denominator = (1.0 / exposureTimeSec).toInt()
    if (denominator > 0 && 1.0 / denominator <= exposureTimeSec + 0.001) {
        return "1/$denominator"s
    }
    return String.format("%.2fs", exposureTimeSec)
}

